-- 33 v3.1 - painel preto e branco para o cliente Roblox.
-- RShift / Insert: menu | RMB / Q: mira | G: speed | F: voo | N: noclip
-- Voo: WASD, Espaco para subir e Ctrl esquerdo para descer.
-- Nao utiliza Drawing, bibliotecas remotas ou carregamento pela internet.
-- Key local: validacao no proprio cliente, sem autenticacao em servidor.
local ACCESS_KEY = "33-ZS2L-F3JG-VZJY"
local LOGO_ASSET_ID = "" -- Opcional: ID da imagem enviada ao Roblox.
local LOGO_BASE64 = [[]]

local cleanup = function() end

local function start()
    local Players = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local Input = game:GetService("UserInputService")
    local HttpService = game:GetService("HttpService")

    assert(RunService:IsClient(), "Execute no cliente, nao em um Script do servidor.")
    local player = Players.LocalPlayer
    assert(player, "LocalPlayer indisponivel. Aguarde entrar na partida.")
    local playerGui = player:WaitForChild("PlayerGui", 15)
    assert(playerGui, "PlayerGui nao carregou em 15 segundos.")

    for _, guiName in ipairs({ "KindoCheatUI", "33UI" }) do
        local oldGui = playerGui:FindFirstChild(guiName)
        if oldGui then
            oldGui:Destroy()
        end
    end

    local ACCENT = Color3.fromRGB(255, 255, 255)
    local State = {
        Aimbot = {
            Enabled = true,
            Active = false,
            FOV = 150,
            Smoothness = 0.15,
            TargetPart = "Head",
            FOVColor = ACCENT,
            ShowFOV = true,
            FOVPosition = "Centro",
            ActivationMode = "Segurar RMB",
            Latched = false,
            TeamCheck = true,
            WallCheck = false,
        },
        ESP = {
            Enabled = true,
            Box = true,
            Skeleton = true,
            Name = true,
            HealthBar = true,
            Distance = true,
            Highlight = true,
            TeamCheck = false,
            Color = ACCENT,
            BoxTransparency = 0.2,
            MaxDistance = 3000,
            LimitDistance = false,
        },
        Noclip = { Enabled = false },
        Fly = { Enabled = false, Speed = 50 },
        Speed = { Enabled = false, Value = 32, Mode = "Sempre" },
        UI = { Open = true },
    }

    local connections = {}
    local records = {}
    local refreshers = {}
    local logoViews = {}
    local collisionSnapshot = {}
    local noclipCharacter = nil
    local espStats = { total = 0, loaded = 0 }
    local espSummary = nil
    local playerBrowser = {
        rows = {}, leaving = {}, selected = nil, active = false, elapsed = 0,
        refresh = function() end, remove = function() end,
    }
    local profiles = { cache = {}, queue = {}, running = false }
    local flight = nil
    local speedSnapshot = nil
    local unlocked = false
    local alive = true
    local focused = true
    local bound = false
    local renderName = "33_" .. HttpService:GenerateGUID(false)
    local activeTarget = nil
    local sliderDrag = nil
    local windowDrag = nil
    local main = nil
    local statusLabel = nil
    local statusMessage = nil
    local statusUntil = 0
    local lastViewport = Vector2.new(0, 0)
    local espElapsed = 0
    local statusElapsed = 0

    local function connect(signal, callback)
        local connection = signal:Connect(callback)
        table.insert(connections, connection)
        return connection
    end

    local function make(className, parent, properties)
        local object = Instance.new(className)
        for key, value in pairs(properties or {}) do
            object[key] = value
        end
        object.Parent = parent
        return object
    end

    local gui = make("ScreenGui", nil, {
        Name = "33UI",
        ResetOnSpawn = false,
        IgnoreGuiInset = true,
        ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
        DisplayOrder = 1000,
    })
    gui.ScreenInsets = Enum.ScreenInsets.None
    local worldVisuals = make("Folder", workspace, { Name = renderName .. "_Visuals" })

    local function refreshAll()
        for _, refresh in ipairs(refreshers) do
            refresh()
        end
    end

    local function message(text)
        statusMessage = text
        statusUntil = os.clock() + 5
        if statusLabel then
            statusLabel.Text = text
        end
    end

    local function characterInfo(who)
        local character = who.Character
        if not character or not character.Parent then
            return nil
        end
        local humanoid = character:FindFirstChildOfClass("Humanoid")
        local root = character:FindFirstChild("HumanoidRootPart")
            or character:FindFirstChild("Torso")
        if not humanoid or humanoid.Health <= 0 or not root or not root:IsA("BasePart") then
            return nil
        end
        return character, humanoid, root
    end

    local function isOpponent(who, teamCheck)
        if who == player then
            return false
        end
        if teamCheck and not who.Neutral and not player.Neutral
            and player.Team ~= nil and who.Team == player.Team then
            return false
        end
        return true
    end

    local function espCharacterInfo(who)
        local character = who.Character
        if not character or not character.Parent then
            return nil
        end
        local root = character:FindFirstChild("HumanoidRootPart")
            or character.PrimaryPart or character:FindFirstChild("Torso")
            or character:FindFirstChild("UpperTorso") or character:FindFirstChild("Head")
            or character:FindFirstChildWhichIsA("BasePart", true)
        if not root or not root:IsA("BasePart") then
            return nil
        end
        return character, character:FindFirstChildOfClass("Humanoid"), root
    end

    local function restoreNoclip()
        for part, original in pairs(collisionSnapshot) do
            if part.Parent then
                pcall(function()
                    part.CanCollide = original
                end)
            end
        end
        table.clear(collisionSnapshot)
        noclipCharacter = nil
    end

    local function updateNoclip()
        if not State.Noclip.Enabled or not unlocked then
            if noclipCharacter then
                restoreNoclip()
            end
            return
        end
        local character = player.Character
        if not character or not character.Parent then
            restoreNoclip()
            return
        end
        if character ~= noclipCharacter then
            restoreNoclip()
            noclipCharacter = character
        end
        for _, part in ipairs(character:GetDescendants()) do
            if part:IsA("BasePart") then
                if collisionSnapshot[part] == nil then
                    collisionSnapshot[part] = part.CanCollide
                end
                if part.CanCollide then
                    part.CanCollide = false
                end
            end
        end
    end

    local function setNoclip(enabled)
        State.Noclip.Enabled = enabled and unlocked
        local applied, noclipError = pcall(updateNoclip)
        if not applied then
            State.Noclip.Enabled = false
            restoreNoclip()
            warn("[33] Erro no noclip: " .. tostring(noclipError))
            message("Erro no noclip; veja o console.")
        end
        refreshAll()
    end

    local function restoreSpeed()
        local previous = speedSnapshot
        speedSnapshot = nil
        if previous and previous.humanoid.Parent then
            previous.humanoid.WalkSpeed = previous.original
        end
    end

    local function updateSpeed()
        if not State.Speed.Enabled or not unlocked then
            restoreSpeed()
            return
        end
        local _, humanoid = characterInfo(player)
        if not humanoid then
            restoreSpeed()
            return
        end
        if not speedSnapshot or speedSnapshot.humanoid ~= humanoid then
            restoreSpeed()
            speedSnapshot = { humanoid = humanoid, original = humanoid.WalkSpeed }
        end
        local active = focused and not Input:GetFocusedTextBox()
        if State.Speed.Mode == "Segurar Shift" then
            active = active and Input:IsKeyDown(Enum.KeyCode.LeftShift)
        end
        local desired = active and State.Speed.Value or speedSnapshot.original
        if humanoid.WalkSpeed ~= desired then
            humanoid.WalkSpeed = desired
        end
    end

    local function setSpeed(enabled)
        State.Speed.Enabled = enabled and unlocked
        local applied, speedError = pcall(updateSpeed)
        if not applied then
            State.Speed.Enabled = false
            pcall(restoreSpeed)
            warn("[33] Erro no speed: " .. tostring(speedError))
            message("Erro no speed; veja o console.")
        end
        refreshAll()
    end

    local function stopFly()
        local previous = flight
        flight = nil
        if not previous then
            return
        end
        for _, key in ipairs({ "velocity", "orientation", "attachment" }) do
            if previous[key] then
                previous[key]:Destroy()
            end
        end
        if previous.root.Parent then
            previous.root.AssemblyLinearVelocity = Vector3.zero
            previous.root.AssemblyAngularVelocity = Vector3.zero
        end
        if previous.humanoid.Parent then
            previous.humanoid.AutoRotate = previous.autoRotate
            previous.humanoid.PlatformStand = previous.platformStand
            if previous.humanoid.Health > 0 and not previous.platformStand then
                previous.humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
            end
        end
    end

    cleanup = function(skipGuiDestroy)
        if not alive then
            return
        end
        alive = false
        State.Aimbot.Active = false
        State.Aimbot.Latched = false
        State.Fly.Enabled = false
        State.Speed.Enabled = false
        State.Noclip.Enabled = false
        if bound then
            RunService:UnbindFromRenderStep(renderName)
            bound = false
        end
        for _, connection in ipairs(connections) do
            connection:Disconnect()
        end
        table.clear(connections)
        restoreNoclip()
        for _, entry in pairs(playerBrowser.rows) do
            for _, connection in ipairs(entry.connections) do
                connection:Disconnect()
            end
        end
        table.clear(playerBrowser.rows)
        table.clear(playerBrowser.leaving)
        table.clear(profiles.queue)
        local speedRestored, speedRestoreError = pcall(restoreSpeed)
        if not speedRestored then
            warn("[33] Erro ao restaurar velocidade: " .. tostring(speedRestoreError))
        end
        local restored, restoreError = pcall(stopFly)
        if not restored then
            warn("[33] Erro ao restaurar personagem: " .. tostring(restoreError))
        end
        worldVisuals:Destroy()
        if not skipGuiDestroy then
            gui:Destroy()
        end
        table.clear(records)
    end
    connect(gui.Destroying, function()
        cleanup(true)
    end)

    local function beginFly()
        local _, humanoid, root = characterInfo(player)
        if not root or root.Anchored or humanoid.Sit then
            message("Voo: personagem indisponivel, sentado ou ancorado.")
            return false
        end
        stopFly()
        -- Registra recursos antes de criar as constraints para limpar falhas parciais.
        flight = {
            root = root,
            humanoid = humanoid,
            autoRotate = humanoid.AutoRotate,
            platformStand = humanoid.PlatformStand,
        }
        flight.attachment = make("Attachment", root, { Name = "33FlightAttachment" })
        flight.velocity = make("LinearVelocity", root, {
            Name = "33FlightVelocity",
            Attachment0 = flight.attachment,
            RelativeTo = Enum.ActuatorRelativeTo.World,
            VelocityConstraintMode = Enum.VelocityConstraintMode.Vector,
            ForceLimitsEnabled = false,
            VectorVelocity = Vector3.zero,
        })
        flight.orientation = make("AlignOrientation", root, {
            Name = "33FlightOrientation",
            Attachment0 = flight.attachment,
            Mode = Enum.OrientationAlignmentMode.OneAttachment,
            MaxTorque = math.huge,
            MaxAngularVelocity = math.huge,
            Responsiveness = 25,
            CFrame = root.CFrame.Rotation,
        })
        humanoid.AutoRotate = false
        humanoid.PlatformStand = true
        return true
    end

    local function setFly(enabled)
        State.Fly.Enabled = false
        if enabled then
            local started, result = pcall(beginFly)
            if started then
                State.Fly.Enabled = result
            else
                pcall(stopFly)
                warn("[33] Erro ao iniciar voo: " .. tostring(result))
                message("Erro ao iniciar voo; veja o console.")
            end
        else
            stopFly()
        end
        refreshAll()
    end

    local function updateFly()
        if not State.Fly.Enabled then
            return
        end
        local _, humanoid, root = characterInfo(player)
        if not flight or not root or root ~= flight.root
            or root.Anchored or humanoid.Sit
            or not flight.velocity.Parent or not flight.orientation.Parent then
            setFly(false)
            return
        end
        local camera = workspace.CurrentCamera
        local direction = Vector3.zero
        if camera and focused and not Input:GetFocusedTextBox() then
            if Input:IsKeyDown(Enum.KeyCode.W) then
                direction = direction + camera.CFrame.LookVector
            end
            if Input:IsKeyDown(Enum.KeyCode.S) then
                direction = direction - camera.CFrame.LookVector
            end
            if Input:IsKeyDown(Enum.KeyCode.D) then
                direction = direction + camera.CFrame.RightVector
            end
            if Input:IsKeyDown(Enum.KeyCode.A) then
                direction = direction - camera.CFrame.RightVector
            end
            if Input:IsKeyDown(Enum.KeyCode.Space) then
                direction = direction + Vector3.yAxis
            end
            if Input:IsKeyDown(Enum.KeyCode.LeftControl) then
                direction = direction - Vector3.yAxis
            end
        end
        if direction.Magnitude > 0 then
            direction = direction.Unit * State.Fly.Speed
        end
        flight.velocity.VectorVelocity = direction
        flight.humanoid.PlatformStand = true
        if camera then
            local look = camera.CFrame.LookVector
            local flatLook = Vector3.new(look.X, 0, look.Z)
            if flatLook.Magnitude > 0.001 then
                flight.orientation.CFrame = CFrame.lookAt(Vector3.zero, flatLook)
            end
        end
    end

    local function teleportTo(who)
        if not unlocked or not alive then
            return
        end
        if not who or who.Parent ~= Players then
            message("Esse jogador saiu do servidor.")
            return
        end
        if who == player then
            message("Esse e o seu proprio personagem.")
            return
        end
        local ownCharacter, ownHumanoid, ownRoot = characterInfo(player)
        local _, _, destination = espCharacterInfo(who)
        if not ownRoot or ownRoot.Anchored then
            message("Seu personagem nao esta disponivel para TP.")
            return
        end
        if not destination then
            message("O personagem desse jogador ainda nao carregou no cliente.")
            return
        end
        local moved, moveError = pcall(function()
            setFly(false)
            ownHumanoid.Sit = false
            ownCharacter:PivotTo(destination.CFrame * CFrame.new(0, 0, 4))
            ownRoot.AssemblyLinearVelocity = Vector3.zero
            ownRoot.AssemblyAngularVelocity = Vector3.zero
        end)
        if moved then
            message("TP ate @" .. who.Name .. ".")
        else
            warn("[33] TP: " .. tostring(moveError))
            message("Nao foi possivel realizar o TP; veja o console.")
        end
    end

    local overlay = make("Frame", gui, {
        Name = "Overlay",
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 1,
    })
    local fovCircle = make("Frame", overlay, {
        Name = "FOV",
        AnchorPoint = Vector2.new(0.5, 0.5),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 5,
    })
    make("UICorner", fovCircle, { CornerRadius = UDim.new(1, 0) })
    local fovStroke = make("UIStroke", fovCircle, {
        Color = State.Aimbot.FOVColor,
        Thickness = 1,
        Transparency = 0.25,
    })

    local R15_LINKS = {
        { "Head", "UpperTorso" }, { "UpperTorso", "LowerTorso" },
        { "UpperTorso", "LeftUpperArm" }, { "LeftUpperArm", "LeftLowerArm" },
        { "LeftLowerArm", "LeftHand" }, { "UpperTorso", "RightUpperArm" },
        { "RightUpperArm", "RightLowerArm" }, { "RightLowerArm", "RightHand" },
        { "LowerTorso", "LeftUpperLeg" }, { "LeftUpperLeg", "LeftLowerLeg" },
        { "LeftLowerLeg", "LeftFoot" }, { "LowerTorso", "RightUpperLeg" },
        { "RightUpperLeg", "RightLowerLeg" }, { "RightLowerLeg", "RightFoot" },
    }
    local R6_LINKS = {
        { "Head", "Torso" }, { "Torso", "Left Arm" },
        { "Torso", "Right Arm" }, { "Torso", "Left Leg" },
        { "Torso", "Right Leg" },
    }
    local CORNERS = {
        Vector3.new(-1, -1, -1), Vector3.new(-1, -1, 1),
        Vector3.new(-1, 1, -1), Vector3.new(-1, 1, 1),
        Vector3.new(1, -1, -1), Vector3.new(1, -1, 1),
        Vector3.new(1, 1, -1), Vector3.new(1, 1, 1),
    }

    local function espText(parent)
        return make("TextLabel", parent, {
            BackgroundTransparency = 1,
            Size = UDim2.fromOffset(260, 18),
            Font = Enum.Font.GothamMedium,
            TextSize = 12,
            TextColor3 = State.ESP.Color,
            TextStrokeColor3 = Color3.new(0, 0, 0),
            TextStrokeTransparency = 0.2,
            TextTruncate = Enum.TextTruncate.AtEnd,
            ZIndex = 4,
        })
    end

    local function addESP(who)
        if who == player or records[who] then
            return
        end
        local container = make("Frame", overlay, {
            Name = "Player_" .. tostring(who.UserId),
            Size = UDim2.fromScale(1, 1),
            BackgroundTransparency = 1,
            Visible = false,
        })
        local box = make("Frame", container, {
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            ZIndex = 2,
        })
        local stroke = make("UIStroke", box, {
            Color = State.ESP.Color,
            Thickness = 1.2,
            Transparency = State.ESP.BoxTransparency,
        })
        local health = make("Frame", container, {
            BackgroundColor3 = Color3.fromRGB(20, 20, 20),
            BorderSizePixel = 0,
            ZIndex = 3,
        })
        local healthFill = make("Frame", health, {
            AnchorPoint = Vector2.new(0, 1),
            Position = UDim2.fromScale(0, 1),
            BackgroundColor3 = ACCENT,
            BorderSizePixel = 0,
            ZIndex = 3,
        })
        local name = espText(container)
        name.AnchorPoint = Vector2.new(0.5, 1)
        name.Text = who.DisplayName .. " (@" .. who.Name .. ")"
        local distance = espText(container)
        distance.AnchorPoint = Vector2.new(0.5, 0)
        local lines = {}
        for index = 1, #R15_LINKS do
            lines[index] = make("Frame", container, {
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundColor3 = State.ESP.Color,
                BorderSizePixel = 0,
                Visible = false,
                ZIndex = 3,
            })
        end
        records[who] = {
            container = container,
            box = box,
            stroke = stroke,
            health = health,
            healthFill = healthFill,
            name = name,
            distance = distance,
            lines = lines,
            links = {},
            character = nil,
            rigRefresh = 0,
            highlight = make("Highlight", worldVisuals, {
                Name = "Player_" .. tostring(who.UserId),
                Enabled = false,
                DepthMode = Enum.HighlightDepthMode.AlwaysOnTop,
                FillColor = State.ESP.Color,
                OutlineColor = State.ESP.Color,
                FillTransparency = 0.85,
                OutlineTransparency = 0.1,
            }),
        }
    end

    local function removeESP(who)
        local record = records[who]
        if record then
            record.container:Destroy()
            record.highlight:Destroy()
            records[who] = nil
        end
    end

    local function hideESP(record)
        record.container.Visible = false
        record.highlight.Enabled = false
    end

    local function refreshRig(record, character, humanoid, now)
        record.character = character
        record.rigRefresh = now + 1
        record.links = {}
        local isR15 = humanoid and humanoid.RigType == Enum.HumanoidRigType.R15
            or character:FindFirstChild("UpperTorso") ~= nil
        local links = isR15 and R15_LINKS or R6_LINKS
        for _, names in ipairs(links) do
            local first = character:FindFirstChild(names[1])
            local second = character:FindFirstChild(names[2])
            if first and first:IsA("BasePart") and second and second:IsA("BasePart") then
                table.insert(record.links, { first, second })
            end
        end
    end

    local function boundsOnScreen(camera, character)
        local bounds, size = character:GetBoundingBox()
        local half = size * 0.5
        local minX, minY = math.huge, math.huge
        local maxX, maxY = -math.huge, -math.huge
        local visibleCorners = 0
        for _, sign in ipairs(CORNERS) do
            local point = bounds:PointToWorldSpace(Vector3.new(
                half.X * sign.X, half.Y * sign.Y, half.Z * sign.Z
            ))
            local screen = camera:WorldToViewportPoint(point)
            if screen.Z > 0.05 then
                visibleCorners = visibleCorners + 1
                minX, minY = math.min(minX, screen.X), math.min(minY, screen.Y)
                maxX, maxY = math.max(maxX, screen.X), math.max(maxY, screen.Y)
            end
        end
        local viewport = camera.ViewportSize
        if visibleCorners == 0 or maxX < 0 or maxY < 0 or minX > viewport.X or minY > viewport.Y then
            return nil
        end
        minX, minY = math.max(minX, 0), math.max(minY, 0)
        maxX, maxY = math.min(maxX, viewport.X), math.min(maxY, viewport.Y)
        return minX, minY, math.max(maxX - minX, 1), math.max(maxY - minY, 1)
    end

    local function drawLine(line, first, second)
        local delta = second - first
        line.Position = UDim2.fromOffset((first.X + second.X) * 0.5, (first.Y + second.Y) * 0.5)
        line.Size = UDim2.fromOffset(delta.Magnitude, 1.5)
        line.Rotation = math.deg(math.atan2(delta.Y, delta.X))
        line.BackgroundColor3 = State.ESP.Color
        line.Visible = true
    end

    local function updateESPRecord(who, record, camera, origin, now)
        espStats.total = espStats.total + 1
        local character, humanoid, root = espCharacterInfo(who)
        if root then
            espStats.loaded = espStats.loaded + 1
        end
        if not State.ESP.Enabled or not root or not isOpponent(who, State.ESP.TeamCheck) then
            hideESP(record)
            return
        end
        local distance = (root.Position - origin).Magnitude
        if State.ESP.LimitDistance and distance > State.ESP.MaxDistance then
            hideESP(record)
            return
        end
        record.highlight.Adornee = character
        record.highlight.Enabled = State.ESP.Highlight
        record.highlight.FillColor = State.ESP.Color
        record.highlight.OutlineColor = State.ESP.Color
        local left, top, width, height = boundsOnScreen(camera, character)
        record.container.Visible = left ~= nil
        if not left then
            return
        end
        record.box.Position = UDim2.fromOffset(left, top)
        record.box.Size = UDim2.fromOffset(width, height)
        record.box.Visible = State.ESP.Box
        record.stroke.Color = State.ESP.Color
        record.stroke.Transparency = State.ESP.BoxTransparency
        record.name.Position = UDim2.fromOffset(left + width * 0.5, top - 3)
        record.name.Visible = State.ESP.Name
        record.name.TextColor3 = State.ESP.Color
        record.distance.Position = UDim2.fromOffset(left + width * 0.5, top + height + 3)
        record.distance.Text = tostring(math.floor(distance + 0.5)) .. " studs"
        record.distance.Visible = State.ESP.Distance
        record.distance.TextColor3 = State.ESP.Color
        local health = 0
        if humanoid then
            health = math.clamp(humanoid.Health / math.max(humanoid.MaxHealth, 1), 0, 1)
        end
        record.health.Position = UDim2.fromOffset(left - 7, top)
        record.health.Size = UDim2.fromOffset(3, height)
        record.health.Visible = State.ESP.HealthBar and humanoid ~= nil
        record.healthFill.Size = UDim2.fromScale(1, health)
        record.healthFill.BackgroundColor3 = State.ESP.Color
        for _, line in ipairs(record.lines) do
            line.Visible = false
        end
        if State.ESP.Skeleton then
            if record.character ~= character or now >= record.rigRefresh then
                refreshRig(record, character, humanoid, now)
            end
            for index, link in ipairs(record.links) do
                if link[1].Parent and link[2].Parent then
                    local first = camera:WorldToViewportPoint(link[1].Position)
                    local second = camera:WorldToViewportPoint(link[2].Position)
                    if first.Z > 0.05 and second.Z > 0.05 then
                        drawLine(record.lines[index], Vector2.new(first.X, first.Y), Vector2.new(second.X, second.Y))
                    end
                end
            end
        end
    end

    local function updateESP(camera)
        local _, _, ownRoot = espCharacterInfo(player)
        local origin = ownRoot and ownRoot.Position or camera.CFrame.Position
        local now = os.clock()
        espStats.total, espStats.loaded = 0, 0
        for who, record in pairs(records) do
            local updated, updateError = pcall(updateESPRecord, who, record, camera, origin, now)
            if not updated then
                hideESP(record)
                if now >= (record.nextWarning or 0) then
                    record.nextWarning = now + 5
                    warn("[33] ESP @" .. who.Name .. ": " .. tostring(updateError))
                end
            end
        end
    end

    local aimRay = RaycastParams.new()
    aimRay.FilterType = Enum.RaycastFilterType.Exclude
    aimRay.IgnoreWater = true

    local function mousePosition(camera)
        if Input.MouseEnabled then
            return Input:GetMouseLocation()
        end
        return camera.ViewportSize * 0.5
    end

    local function aimOrigin(camera)
        if State.Aimbot.FOVPosition == "Mouse" then
            return mousePosition(camera)
        end
        return camera.ViewportSize * 0.5
    end

    local function pointerInMenu(position)
        if not main or not main.Visible then
            return false
        end
        local origin, size = main.AbsolutePosition, main.AbsoluteSize
        return position.X >= origin.X and position.X <= origin.X + size.X
            and position.Y >= origin.Y and position.Y <= origin.Y + size.Y
    end

    local function aimPart(character, root)
        local part
        if State.Aimbot.TargetPart == "Chest" then
            part = character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso")
        else
            part = character:FindFirstChild(State.Aimbot.TargetPart)
        end
        if part and part:IsA("BasePart") then
            return part
        end
        return root
    end

    local function updateAim(camera, deltaTime)
        State.Aimbot.Active = false
        activeTarget = nil
        if not State.Aimbot.Enabled then
            State.Aimbot.Latched = false
            fovCircle.Visible = false
            return
        end
        local origin = aimOrigin(camera)
        local mouse = mousePosition(camera)
        fovCircle.Position = UDim2.fromOffset(origin.X, origin.Y)
        fovCircle.Size = UDim2.fromOffset(State.Aimbot.FOV * 2, State.Aimbot.FOV * 2)
        fovCircle.Visible = focused and State.Aimbot.Enabled and State.Aimbot.ShowFOV
        fovStroke.Color = State.Aimbot.FOVColor
        local requested = State.Aimbot.ActivationMode == "Alternar Q" and State.Aimbot.Latched
            or State.Aimbot.ActivationMode == "Segurar RMB"
                and Input:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)
        if not unlocked or not focused or Input:GetFocusedTextBox() or not requested
            or pointerInMenu(mouse) then
            return
        end
        local ownCharacter = characterInfo(player)
        if not ownCharacter then
            return
        end
        if State.Aimbot.WallCheck then
            aimRay.FilterDescendantsInstances = { ownCharacter, camera, worldVisuals }
        end
        local bestPart = nil
        local bestPlayer = nil
        local bestDistance = State.Aimbot.FOV
        for _, who in ipairs(Players:GetPlayers()) do
            if isOpponent(who, State.Aimbot.TeamCheck) then
                local character, _, root = characterInfo(who)
                if root then
                    local part = aimPart(character, root)
                    local screen, onScreen = camera:WorldToViewportPoint(part.Position)
                    if onScreen and screen.Z > 0 then
                        local distance = (Vector2.new(screen.X, screen.Y) - origin).Magnitude
                        if distance <= bestDistance then
                            local visible = true
                            if State.Aimbot.WallCheck then
                                local direction = part.Position - camera.CFrame.Position
                                local result = workspace:Raycast(camera.CFrame.Position, direction, aimRay)
                                visible = result == nil or result.Instance:IsDescendantOf(character)
                            end
                            if visible then
                                bestDistance = distance
                                bestPart = part
                                bestPlayer = who
                            end
                        end
                    end
                end
            end
        end
        if bestPart and (bestPart.Position - camera.CFrame.Position).Magnitude > 0.001 then
            local factor = math.clamp(State.Aimbot.Smoothness, 0.01, 1)
            local alpha = 1 - (1 - factor) ^ (math.clamp(deltaTime, 0, 0.1) * 60)
            camera.CFrame = camera.CFrame:Lerp(CFrame.lookAt(camera.CFrame.Position, bestPart.Position), alpha)
            State.Aimbot.Active = true
            activeTarget = bestPlayer
            fovStroke.Color = Color3.new(1, 1, 1)
        end
    end

