    function profiles.requester()
        if type(request) == "function" then
            return request
        elseif type(http_request) == "function" then
            return http_request
        elseif type(http) == "table" and type(http.request) == "function" then
            return http.request
        elseif type(syn) == "table" and type(syn.request) == "function" then
            return syn.request
        end
        return nil
    end

    function profiles.fetch(userId)
        local requester = profiles.requester()
        assert(requester, "Consulta HTTP indisponivel neste executor.")
        local response = requester({
            Url = "https://users.roblox.com/v1/users/" .. string.format("%.0f", userId),
            Method = "GET",
            Headers = { ["Accept"] = "application/json" },
            Timeout = 10,
        })
        assert(type(response) == "table", "Resposta HTTP invalida.")
        local status = tonumber(response.StatusCode or response.Status or response.status_code)
        assert(status == 200, "Consulta publica retornou HTTP " .. tostring(status) .. ".")
        local body = response.Body or response.body
        assert(type(body) == "string", "Resposta publica sem conteudo.")
        local data = HttpService:JSONDecode(body)
        assert(type(data) == "table" and tonumber(data.id) == userId, "Perfil publico inesperado.")
        assert(type(data.created) == "string" and data.created:match("^%d%d%d%d%-%d%d%-%d%dT"), "Data de criacao indisponivel.")
        return {
            created = data.created,
            description = type(data.description) == "string" and data.description or "",
            verified = data.hasVerifiedBadge == true,
        }
    end

    function profiles.load(who, force)
        if not alive or not unlocked or not who then
            return
        end
        local userId = who.UserId
        local current = profiles.cache[userId]
        if current then
            if current.loading then
                if force then
                    message("A consulta dessa conta ja esta em andamento.")
                end
                return
            end
            if not force then
                return
            end
            local waitSeconds = math.ceil((current.retryAt or 0) - os.clock())
            if waitSeconds > 0 then
                message("Aguarde " .. waitSeconds .. "s para consultar essa conta novamente.")
                return
            end
        end
        local entry = { loading = false, retryAt = os.clock() + 20 }
        profiles.cache[userId] = entry
        if userId <= 0 then
            entry.error = "Conta de teste: perfil publico indisponivel."
            playerBrowser.refresh()
            return
        end
        if not profiles.requester() then
            entry.error = "Consulta publica indisponivel neste executor."
            playerBrowser.refresh()
            return
        end
        entry.loading = true
        table.insert(profiles.queue, { id = userId, entry = entry })
        playerBrowser.refresh()
        if profiles.running then
            return
        end
        profiles.running = true
        task.spawn(function()
            while alive and #profiles.queue > 0 do
                local job = table.remove(profiles.queue, 1)
                local loaded, result = pcall(profiles.fetch, job.id)
                if not alive then
                    break
                end
                job.entry.loading = false
                job.entry.retryAt = os.clock() + 20
                if loaded then
                    job.entry.data = result
                else
                    job.entry.error = "Nao foi possivel consultar o perfil publico."
                    warn("[33] Perfil " .. tostring(job.id) .. ": " .. tostring(result))
                end
                local refreshed, refreshError = pcall(playerBrowser.refresh)
                if not refreshed then
                    warn("[33] Atualizacao do perfil: " .. tostring(refreshError))
                end
                task.wait(1)
            end
            profiles.running = false
        end)
    end

    function profiles.dates(who)
        local entry = profiles.cache[who.UserId]
        local data = entry and entry.data
        if data then
            local year, month, day = data.created:match("^(%d%d%d%d)%-(%d%d)%-(%d%d)")
            local created = day .. "/" .. month .. "/" .. year .. " (UTC, API publica)"
            local parsed, timestamp = pcall(DateTime.fromIsoDate, data.created)
            if parsed and timestamp then
                local days = math.max(0, math.floor((DateTime.now().UnixTimestamp - timestamp.UnixTimestamp) / 86400))
                return created, tostring(days) .. " dias"
            end
            return created, "Indisponivel"
        end
        -- AccountAge nao replica para outros Players; nao transformar 0 em data falsa.
        if who == player then
            local days = tonumber(who.AccountAge)
            if days and days >= 0 then
                local estimate = os.date("!%d/%m/%Y", os.time() - days * 86400)
                return estimate .. " (estimativa UTC)", tostring(days) .. " dias (cliente)"
            end
        end
        return "Indisponivel sem consulta publica", "Indisponivel sem consulta publica"
    end

