    local function toggle(parent, text, getValue, setValue)
        local frame = row(parent, 30)
        local caption = label(frame, text)
        caption.Size = UDim2.new(1, -78, 1, 0)
        local control = button(frame, "")
        control.Size = UDim2.fromOffset(64, 26)
        control.Position = UDim2.new(1, -64, 0.5, -13)
        local function refresh()
            local enabled = getValue()
            control.Text = enabled and "ON" or "OFF"
            control.BackgroundColor3 = enabled and ACCENT or Color3.fromRGB(66, 66, 66)
            control.TextColor3 = enabled and Color3.fromRGB(10, 10, 10) or Color3.new(1, 1, 1)
        end
        table.insert(refreshers, refresh)
        connect(control.Activated, function()
            setValue(not getValue())
            refresh()
        end)
        refresh()
    end

