    local function slider(parent, text, minimum, maximum, initial, callback, suffix)
        local frame = row(parent, 54)
        local caption = label(frame, text .. (suffix and " (" .. suffix:gsub("^%s+", "") .. ")" or ""))
        caption.Size = UDim2.new(1, -82, 0, 24)
        local valueBox = make("TextBox", frame, {
            Size = UDim2.fromOffset(72, 24),
            Position = UDim2.new(1, -72, 0, 0),
            Text = tostring(initial),
            PlaceholderText = tostring(minimum) .. "-" .. tostring(maximum),
            ClearTextOnFocus = false,
            MultiLine = false,
            BackgroundColor3 = Color3.fromRGB(8, 8, 8),
            TextColor3 = ACCENT,
            Font = Enum.Font.GothamMedium,
            TextSize = 13,
            BorderSizePixel = 0,
        })
        round(valueBox, 5)
        make("UIStroke", valueBox, {
            ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
            Color = Color3.fromRGB(110, 110, 110),
            Thickness = 1,
        })
        local track = make("Frame", frame, {
            Size = UDim2.new(1, -8, 0, 7),
            Position = UDim2.new(0, 4, 0, 35),
            BackgroundColor3 = Color3.fromRGB(56, 56, 56),
            BorderSizePixel = 0,
        })
        round(track, 4)
        local fill = make("Frame", track, {
            BackgroundColor3 = ACCENT,
            BorderSizePixel = 0,
        })
        round(fill, 4)
        local handle = make("Frame", track, {
            Size = UDim2.fromOffset(14, 14),
            AnchorPoint = Vector2.new(0.5, 0.5),
            BackgroundColor3 = Color3.new(1, 1, 1),
            BorderSizePixel = 0,
        })
        round(handle, 7)
        local hit = make("TextButton", frame, {
            Text = "",
            Size = UDim2.new(1, 0, 0, 28),
            Position = UDim2.fromOffset(0, 25),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            ZIndex = 2,
        })
        local current = initial
        local function render(value)
            local ratio = (value - minimum) / (maximum - minimum)
            fill.Size = UDim2.fromScale(ratio, 1)
            handle.Position = UDim2.fromScale(ratio, 0.5)
            valueBox.Text = tostring(value)
        end
        local function setValue(value)
            value = math.clamp(math.floor(value + 0.5), minimum, maximum)
            render(value)
            if value ~= current then
                current = value
                callback(value)
            end
        end
        local function update(x)
            if track.AbsoluteSize.X <= 0 then
                return
            end
            local ratio = math.clamp((x - track.AbsolutePosition.X) / track.AbsoluteSize.X, 0, 1)
            setValue(minimum + ratio * (maximum - minimum))
        end
        connect(hit.InputBegan, function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1
                or input.UserInputType == Enum.UserInputType.Touch then
                sliderDrag = { input = input, update = update }
                update(input.Position.X)
            end
        end)
        connect(valueBox.FocusLost, function()
            local value = tonumber((valueBox.Text:gsub(",", ".")))
            if value and value == value and value > -math.huge and value < math.huge then
                setValue(value)
            else
                render(current)
                message("Digite um numero entre " .. minimum .. " e " .. maximum .. ".")
            end
        end)
        render(initial)
    end

