    function playerBrowser.remove(who)
        playerBrowser.leaving[who] = true
        local entry = playerBrowser.rows[who]
        if entry then
            for _, connection in ipairs(entry.connections) do
                connection:Disconnect()
            end
            entry.frame:Destroy()
            playerBrowser.rows[who] = nil
        end
        if playerBrowser.selected == who then
            playerBrowser.selected = nil
            playerInfo.Text = "O jogador selecionado saiu do servidor."
        end
    end

    function playerBrowser.refresh()
        if not alive then
            return
        end
        local query = string.lower((playerSearch.Text:gsub("^%s+", ""):gsub("%s+$", ""):gsub("^@", "")))
        local allPlayers = Players:GetPlayers()
        table.sort(allPlayers, function(first, second)
            local a, b = string.lower(first.DisplayName), string.lower(second.DisplayName)
            if a == b then
                return first.UserId < second.UserId
            end
            return a < b
        end)
        local total, shown = 0, 0
        for index, who in ipairs(allPlayers) do
            if not playerBrowser.leaving[who] then
                total = total + 1
                local currentPlayer = who
                local entry = playerBrowser.rows[who]
                if not entry then
                    local frame = make("Frame", playerList, {
                        Size = UDim2.new(1, -6, 0, 48),
                        BackgroundColor3 = Color3.fromRGB(18, 18, 18),
                        BorderSizePixel = 0,
                    })
                    round(frame, 6)
                    local select = button(frame, "")
                    select.Size = UDim2.new(1, -64, 1, 0)
                    select.BackgroundTransparency = 1
                    select.TextColor3 = ACCENT
                    select.TextXAlignment = Enum.TextXAlignment.Left
                    select.TextSize = 11
                    make("UIPadding", select, { PaddingLeft = UDim.new(0, 6) })
                    local tp = button(frame, who == player and "VOCE" or "TP")
                    tp.Size = UDim2.fromOffset(52, 30)
                    tp.Position = UDim2.new(1, -58, 0.5, -15)
                    tp.TextSize = 10
                    tp.Active = who ~= player
                    tp.AutoButtonColor = who ~= player
                    entry = { frame = frame, select = select, tp = tp, connections = {} }
                    playerBrowser.rows[who] = entry
                    table.insert(entry.connections, select.Activated:Connect(function()
                        playerBrowser.selected = currentPlayer
                        playerBrowser.refresh()
                        profiles.load(currentPlayer, false)
                    end))
                    table.insert(entry.connections, tp.Activated:Connect(function()
                        teleportTo(currentPlayer)
                    end))
                end
                local haystack = string.lower(who.DisplayName .. " " .. who.Name .. " " .. tostring(who.UserId))
                local visible = query == "" or string.find(haystack, query, 1, true) ~= nil
                entry.frame.Visible = visible
                entry.frame.LayoutOrder = index
                entry.frame.BackgroundColor3 = playerBrowser.selected == who
                    and Color3.fromRGB(55, 55, 55) or Color3.fromRGB(18, 18, 18)
                entry.select.Text = who.DisplayName .. "\n@" .. who.Name .. (who == player and " (voce)" or "")
                if visible then
                    shown = shown + 1
                end
            end
        end
        playerCount.Text = tostring(shown) .. " exibidos / " .. tostring(total) .. " no servidor (inclui voce)"
        local who = playerBrowser.selected
        if not who or who.Parent ~= Players then
            return
        end
        local character, humanoid, root = espCharacterInfo(who)
        local _, _, ownRoot = espCharacterInfo(player)
        local created, age = profiles.dates(who)
        local info = {
            "NOME: " .. who.DisplayName,
            "USUARIO: @" .. who.Name,
            "USER ID: " .. tostring(who.UserId),
            "CRIACAO: " .. created,
            "IDADE DA CONTA: " .. age,
            "EQUIPE: " .. (who.Team and who.Team.Name or "Sem equipe"),
            "PERSONAGEM: " .. (character and "Carregado no cliente" or "Aguardando carregamento"),
        }
        if humanoid then
            table.insert(info, "VIDA: " .. math.floor(humanoid.Health + 0.5) .. " / " .. math.floor(humanoid.MaxHealth + 0.5))
            table.insert(info, "VELOCIDADE: " .. math.floor(humanoid.WalkSpeed + 0.5) .. " studs/s")
        end
        if root then
            local position = root.Position
            table.insert(info, string.format("POSICAO: %.0f, %.0f, %.0f", position.X, position.Y, position.Z))
            if ownRoot then
                table.insert(info, "DISTANCIA: " .. math.floor((position - ownRoot.Position).Magnitude + 0.5) .. " studs")
            end
        end
        local entry = profiles.cache[who.UserId]
        if entry and entry.data then
            table.insert(info, "SELO VERIFICADO: " .. (entry.data.verified and "Sim" or "Nao"))
            table.insert(info, "DESCRICAO PUBLICA: " .. (entry.data.description ~= "" and entry.data.description or "Sem descricao"))
        elseif entry and entry.loading then
            table.insert(info, "Consultando perfil publico...")
        elseif entry and entry.error then
            table.insert(info, entry.error)
        end
        table.insert(info, "PERFIL: https://www.roblox.com/users/" .. who.UserId .. "/profile")
        playerInfo.Text = table.concat(info, "\n")
    end

