    local function validateKey()
        if unlocked or not alive then
            return
        end
        local entered = string.upper((keyBox.Text:gsub("%s+", "")))
        if entered ~= ACCESS_KEY then
            keyFeedback.Text = "Key incorreta. Confira e tente novamente."
            return
        end
        unlocked = true
