    local function beginWindowDrag(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            windowDrag = {
                input = input,
                origin = Vector2.new(input.Position.X, input.Position.Y),
                position = main.Position,
            }
        end
    end
    connect(header.InputBegan, beginWindowDrag)
    connect(title.InputBegan, beginWindowDrag)

    connect(Input.InputChanged, function(input)
        if sliderDrag and (input.UserInputType == Enum.UserInputType.MouseMovement
            or input == sliderDrag.input) then
            sliderDrag.update(input.Position.X)
        end
        if windowDrag and (input.UserInputType == Enum.UserInputType.MouseMovement
            or input == windowDrag.input) then
            local delta = Vector2.new(input.Position.X, input.Position.Y) - windowDrag.origin
            main.Position = UDim2.fromOffset(
                windowDrag.position.X.Offset + delta.X,
                windowDrag.position.Y.Offset + delta.Y
            )
            constrainWindow()
        end
    end)
    connect(Input.InputEnded, function(input)
        if sliderDrag and (input == sliderDrag.input
            or input.UserInputType == Enum.UserInputType.MouseButton1) then
            sliderDrag = nil
        end
        if windowDrag and (input == windowDrag.input
            or input.UserInputType == Enum.UserInputType.MouseButton1) then
            windowDrag = nil
        end
    end)
    connect(Input.InputBegan, function(input, processed)
        if not unlocked or processed or Input:GetFocusedTextBox() then
            return
        end
        if input.KeyCode == Enum.KeyCode.RightShift or input.KeyCode == Enum.KeyCode.Insert then
            setMenu(not State.UI.Open)
        elseif input.KeyCode == Enum.KeyCode.F then
            setFly(not State.Fly.Enabled)
        elseif input.KeyCode == Enum.KeyCode.G then
            setSpeed(not State.Speed.Enabled)
        elseif input.KeyCode == Enum.KeyCode.N then
            setNoclip(not State.Noclip.Enabled)
        elseif input.KeyCode == Enum.KeyCode.Q and State.Aimbot.ActivationMode == "Alternar Q"
            and State.Aimbot.Enabled then
            State.Aimbot.Latched = not State.Aimbot.Latched
        end
    end)
