        end
        local speedOK, speedError = pcall(updateSpeed)
        if not speedOK then
            State.Speed.Enabled = false
            pcall(restoreSpeed)
            reportFailure("speed", speedError)
        end
        local noclipOK, noclipError = pcall(updateNoclip)
        if not noclipOK then
            State.Noclip.Enabled = false
            restoreNoclip()
            reportFailure("noclip", noclipError)
        end
        if State.Fly.Enabled then
            local ok, err = pcall(updateFly)
            if not ok then
                State.Fly.Enabled = false
                pcall(stopFly)
                reportFailure("voo", err)
            end
        end
    end)

    -- Executa depois da atualizacao padrao da camera.
    RunService:BindToRenderStep(renderName, Enum.RenderPriority.Camera.Value + 1, function(deltaTime)
        if not alive then
            return
        end
        local camera = workspace.CurrentCamera
        if not camera then
            return
        end
        if camera.ViewportSize ~= lastViewport then
            constrainWindow()
        end
        if not unlocked then
            fovCircle.Visible = false
            return
        end
        local aimOK, aimError = pcall(updateAim, camera, deltaTime)
        if not aimOK then
            State.Aimbot.Enabled = false
            State.Aimbot.Active = false
            State.Aimbot.Latched = false
            activeTarget = nil
            fovCircle.Visible = false
            reportFailure("mira", aimError)
        end
        espElapsed = espElapsed + deltaTime
        if espElapsed >= 1 / 30 then
            espElapsed = espElapsed % (1 / 30)
            local espOK, espError = pcall(updateESP, camera)
            if not espOK then
                State.ESP.Enabled = false
                for _, record in pairs(records) do
                    hideESP(record)
                end
                reportFailure("ESP", espError)
            end
        end
        statusElapsed = statusElapsed + deltaTime
        playerBrowser.elapsed = playerBrowser.elapsed + deltaTime
        if playerBrowser.active and State.UI.Open and playerBrowser.elapsed >= 0.5 then
            playerBrowser.elapsed = 0
            local browserOK, browserError = pcall(playerBrowser.refresh)
            if not browserOK then
                warn("[33] Players: " .. tostring(browserError))
                playerBrowser.active = false
                message("Erro ao atualizar Players; veja o console.")
            end
        end
        if statusElapsed >= 0.15 then
            statusElapsed = 0
            espSummary.Text = "Personagens carregados: " .. espStats.loaded .. " / " .. espStats.total
                .. ". Aliados e distancia: filtros opcionais."
            if statusMessage and os.clock() < statusUntil then
                statusLabel.Text = statusMessage
            else
                statusMessage = nil
                local waiting = State.Aimbot.ActivationMode == "Alternar Q" and "Q" or "RMB"
                local aimStatus = State.Aimbot.Enabled and waiting or "OFF"
                if activeTarget then
                    aimStatus = activeTarget.DisplayName
                end
                local speedStatus = State.Speed.Enabled and tostring(State.Speed.Value) or "OFF"
                statusLabel.Text = "Mira: " .. aimStatus .. " | Speed: " .. speedStatus
                    .. " | Voo: " .. (State.Fly.Enabled and "ON" or "OFF")
            end
        end
    end)
    bound = true

    local function decodeBase64(data)
        local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        local lookup = {}
        for index = 1, #alphabet do
            lookup[alphabet:byte(index)] = index - 1
        end
        local chunks, block = {}, {}
        for index = 1, #data, 4 do
            if index % 131072 == 1 then
                if not alive then
                    return nil
                end
                task.wait()
            end
            local first = lookup[data:byte(index)] or 0
            local second = lookup[data:byte(index + 1)] or 0
            local third = lookup[data:byte(index + 2)] or 0
            local fourth = lookup[data:byte(index + 3)] or 0
            local value = first * 262144 + second * 4096 + third * 64 + fourth
            local a = math.floor(value / 65536) % 256
            local b = math.floor(value / 256) % 256
            local c = value % 256
            if data:byte(index + 2) == 61 then
                block[#block + 1] = string.char(a)
            elseif data:byte(index + 3) == 61 then
                block[#block + 1] = string.char(a, b)
            else
                block[#block + 1] = string.char(a, b, c)
            end
            if #block >= 2048 then
                chunks[#chunks + 1] = table.concat(block)
                table.clear(block)
            end
        end
        chunks[#chunks + 1] = table.concat(block)
        return table.concat(chunks)
    end

    local function resolveLogo()
        if LOGO_ASSET_ID ~= "" then
            if LOGO_ASSET_ID:match("^%d+$") then
                return "rbxassetid://" .. LOGO_ASSET_ID
            end
            return LOGO_ASSET_ID
        end
        local assetGetter = nil
        if type(getcustomasset) == "function" then
            assetGetter = getcustomasset
        elseif type(getsynasset) == "function" then
            assetGetter = getsynasset
        end
        if type(writefile) ~= "function" or not assetGetter then
            warn("[33] Imagem local indisponivel. Use LOGO_ASSET_ID para a logo no Roblox Studio.")
            return nil
        end
        local filename = "33-logo-5768a2ce.png"
        if type(isfile) ~= "function" or not isfile(filename) then
            local bytes = decodeBase64(LOGO_BASE64)
            if not bytes or not alive then
                return nil
            end
            writefile(filename, bytes)
        end
        return assetGetter(filename)
    end

    local function loadLogo()
        local loaded, asset = pcall(resolveLogo)
        if not alive then
            return
        end
        if not loaded then
            warn("[33] Nao foi possivel carregar a logo: " .. tostring(asset))
            return
        end
        if type(asset) ~= "string" or asset == "" then
            return
        end
        for _, view in ipairs(logoViews) do
            local current = view
            current.image.Image = asset
            current.image.Visible = true
            local function refreshLogo()
                current.fallback.Visible = not current.image.IsLoaded
            end
            connect(current.image:GetPropertyChangedSignal("IsLoaded"), refreshLogo)
            refreshLogo()
        end
    end

    gui.Parent = playerGui
    setMenu(false)
    task.spawn(loadLogo)
    print("[33] Aguardando key. RShift: menu | G: speed | F: voo | RMB / Q: mira.")
end

local ok, err = xpcall(start, debug.traceback)
if not ok then
